"use client";

import { useId } from "react";
import { LexicalEditor } from "lexical";
import {
  InitialConfigType,
  LexicalComposer,
} from "@lexical/react/LexicalComposer";
import {
  $convertFromMarkdownString,
  CHECK_LIST,
  ELEMENT_TRANSFORMERS,
  MULTILINE_ELEMENT_TRANSFORMERS,
  TEXT_FORMAT_TRANSFORMERS,
  TEXT_MATCH_TRANSFORMERS,
  TRANSFORMERS,
} from "@lexical/markdown";

import { editorTheme } from "@/components/Editor/themes/editor-theme";
import { TooltipProvider } from "@/components/ui/Tooltip";
import { HR } from "@/components/Editor/transformers/markdown-hr-transformer";
import { IMAGE } from "@/components/Editor/transformers/markdown-image-transformer";

import { nodes } from "./nodes";
import { Plugins } from "./plugins";

export function Editor({
  editorState,
  onChange,
}: {
  editorState?: string;
  onChange?: (editorState: any) => void;
}) {
  const editorId = useId();

  const editorConfig: InitialConfigType = {
    namespace: `Editor-${editorId}`,
    theme: editorTheme,
    nodes,
    onError: (error: Error) => {
      console.error("Error in editor", error);
    },
  };

  return (
    <div className="bg-gray-2 border border-gray-6 rounded-md">
      <LexicalComposer
        initialConfig={{
          ...editorConfig,
          editorState: (editor: LexicalEditor) => {
            editor.update(() => {
              if (!editorState) return;
              $convertFromMarkdownString(
                editorState,
                [HR, IMAGE, CHECK_LIST, ...TRANSFORMERS],
                undefined,
                true
              );
            });
          },
        }}
      >
        <TooltipProvider>
          <Plugins onChange={onChange} />
        </TooltipProvider>
      </LexicalComposer>
    </div>
  );
}

import { useState } from "react";
import { LexicalErrorBoundary } from "@lexical/react/LexicalErrorBoundary";
import { RichTextPlugin } from "@lexical/react/LexicalRichTextPlugin";
import { ListPlugin } from "@lexical/react/LexicalListPlugin";
import { ClickableLinkPlugin } from "@lexical/react/LexicalClickableLinkPlugin";
import { MarkdownShortcutPlugin } from "@lexical/react/LexicalMarkdownShortcutPlugin";
import { LinkPlugin } from "@lexical/react/LexicalLinkPlugin";
import { HistoryPlugin } from "@lexical/react/LexicalHistoryPlugin";
import {
  CHECK_LIST,
  ELEMENT_TRANSFORMERS,
  MULTILINE_ELEMENT_TRANSFORMERS,
  TEXT_FORMAT_TRANSFORMERS,
  TEXT_MATCH_TRANSFORMERS,
  TRANSFORMERS,
} from "@lexical/markdown";

import { FloatingLinkEditorPlugin } from "@/components/Editor/plugins/floating-link-editor-plugin";
import { AutoLinkPlugin } from "@/components/Editor/editor-ui/auto-link-plugin";

import { ContentEditable } from "@/components/Editor/editor-ui/content-editable";
import { ToolbarPlugin } from "@/components/Editor/plugins/toolbar/toolbar-plugin";
import { FontFormatToolbarPlugin } from "@/components/Editor/plugins/toolbar/font-format-toolbar-plugin";
import { BlockFormatDropDown } from "@/components/Editor/plugins/toolbar/block-format-toolbar-plugin";
import { FormatParagraph } from "@/components/Editor/plugins/toolbar/block-format/format-paragraph";
import { FormatHeading } from "@/components/Editor/plugins/toolbar/block-format/format-heading";
import { FormatNumberedList } from "@/components/Editor/plugins/toolbar/block-format/format-numbered-list";
import { FormatBulletedList } from "@/components/Editor/plugins/toolbar/block-format/format-bulleted-list";
import { FormatQuote } from "@/components/Editor/plugins/toolbar/block-format/format-quote";
import { LinkToolbarPlugin } from "@/components/Editor/plugins/toolbar/link-toolbar-plugin";
import { HR } from "@/components/Editor/transformers/markdown-hr-transformer";
import { IMAGE } from "@/components/Editor/transformers/markdown-image-transformer";

import { ImagesPlugin } from "@/components/Editor/plugins/images-plugin";
import { InsertImage } from "@/components/Editor/plugins/insert-image";
import { MarkdownTogglePlugin } from "@/components/Editor/plugins/actions/markdown-toggle-plugin";
import { ConverToMarkdownChangePlugin } from "@/components/Editor/plugins/converto-to-markdown-change";
import { HistoryToolbarPlugin } from "@/components/Editor/plugins/toolbar/history-toolbar-plugin";

export function Plugins({ onChange }: { onChange?: (state: any) => void }) {
  const [floatingAnchorElem, setFloatingAnchorElem] =
    useState<HTMLDivElement | null>(null);

  const [isLinkEditMode, setIsLinkEditMode] = useState<boolean>(false);

  const onRef = (_floatingAnchorElem: HTMLDivElement) => {
    if (_floatingAnchorElem !== null) {
      setFloatingAnchorElem(_floatingAnchorElem);
    }
  };

  return (
    <>
      <ToolbarPlugin>
        {({ blockType }) => (
          <div className="flex items-center gap-0.5 overflow-auto px-1 top-0 z-5 bg-gray-1 rounded-t-md p-0.5 border-b border-gray-a6 justify-between">
            <div>
              <HistoryToolbarPlugin />
            </div>

            <div className=" items-center gap-0.5 flex">
              <BlockFormatDropDown>
                <FormatParagraph />
                <FormatHeading levels={["h1", "h2", "h3"]} />
                <FormatNumberedList />
                <FormatBulletedList />
                <FormatQuote />
              </BlockFormatDropDown>
              <FontFormatToolbarPlugin format="bold" />
              <FontFormatToolbarPlugin format="italic" />
              <FontFormatToolbarPlugin format="underline" />
              <FontFormatToolbarPlugin format="strikethrough" />
              <LinkToolbarPlugin setIsLinkEditMode={setIsLinkEditMode} />
              <InsertImage />
            </div>
            <div>
              <MarkdownTogglePlugin
                transformers={[
                  HR,
                  IMAGE,
                  CHECK_LIST,
                  ...ELEMENT_TRANSFORMERS,
                  ...MULTILINE_ELEMENT_TRANSFORMERS,
                  ...TEXT_FORMAT_TRANSFORMERS,
                  ...TEXT_MATCH_TRANSFORMERS,
                ]}
                shouldPreserveNewLinesInMarkdown={true}
              />
            </div>
          </div>
        )}
      </ToolbarPlugin>
      <RichTextPlugin
        contentEditable={
          <div className="">
            <div className="relative" ref={onRef}>
              <ContentEditable placeholder="Comienza a escribir algo ..." />
            </div>
          </div>
        }
        ErrorBoundary={LexicalErrorBoundary}
      />
      <HistoryPlugin />
      <ListPlugin />
      {/* <CheckListPlugin /> */}
      <ClickableLinkPlugin />
      <AutoLinkPlugin />
      <LinkPlugin />
      <FloatingLinkEditorPlugin
        anchorElem={floatingAnchorElem}
        isLinkEditMode={isLinkEditMode}
        setIsLinkEditMode={setIsLinkEditMode}
      />
      <ImagesPlugin />
      <MarkdownShortcutPlugin
        transformers={[
          HR,
          IMAGE,
          CHECK_LIST,
          ...ELEMENT_TRANSFORMERS,
          ...MULTILINE_ELEMENT_TRANSFORMERS,
          ...TEXT_FORMAT_TRANSFORMERS,
          ...TEXT_MATCH_TRANSFORMERS,
          ...TRANSFORMERS,
        ]}
      />

      {/* actions plugins */}
      {onChange && <ConverToMarkdownChangePlugin onChange={onChange} />}
    </>
  );
}

"use client"

import { useId, useState } from "react"
import { InitialConfigType, LexicalComposer } from "@lexical/react/LexicalComposer"
import { RichTextPlugin } from "@lexical/react/LexicalRichTextPlugin"
import { ContentEditable } from "@lexical/react/LexicalContentEditable"
import { LexicalErrorBoundary } from "@lexical/react/LexicalErrorBoundary"
import { ListPlugin } from "@lexical/react/LexicalListPlugin"
import { ClickableLinkPlugin } from "@lexical/react/LexicalClickableLinkPlugin"
import { $convertFromMarkdownString, CHECK_LIST, TRANSFORMERS } from "@lexical/markdown"
import { LexicalEditor } from "lexical"
import { PlayIcon } from "@radix-ui/react-icons"

import { editorTheme } from "@/components/Editor/themes/editor-theme"
import { nodes } from "./nodes"
import { HR } from "@/components/Editor/transformers/markdown-hr-transformer"
import { IMAGE } from "@/components/Editor/transformers/markdown-image-transformer"
import Button from "@/components/ui/Button"
import { ScrollArea, ScrollBar } from "@/components/ui/ScrollArea"

export function Viewer({ content, height }: { content: string, height?: string }) {
  const viewerId = useId();

  const viewerConfig: InitialConfigType = {
    namespace: `Viewer-${viewerId}`,
    theme: editorTheme,
    nodes,
    editable: false,
    onError: (error: Error) => {
      console.error("Error in viewer", error)
    },
  };
  const [isMarkdownView, setIsMarkdownView] = useState(false)

  if (isMarkdownView) {
    return (
      <div className="bg-gray-2 border border-gray-6 rounded-sm p-1 cursor-default">
        <div className="flex justify-end items-center mb-0.5 pb-0.5 border-b border-gray-6">

          <Button
            mode="pill"
            onClick={() => setIsMarkdownView(false)}
            className={`bg-gray-2 border border-gray-6 text-gray-12 size-3`}

          >
            <PlayIcon className="icon" />
          </Button>
        </div>
        <ScrollArea className="w-full rounded-sm" style={{ height: height || '400px' }}>
          <pre className="text-gray-12 bg-gray-1 border border-gray-6 p-1 rounded-sm max-w-full">
            <code className="text-sm font-mono whitespace-pre-wrap break-words cursor-text">
              {content}
            </code>
          </pre>
          <ScrollBar orientation="horizontal" />
        </ScrollArea>
      </div>
    )
  }

  return (
    <div className="bg-gray-2 border border-gray-6 rounded-sm p-1 cursor-default">
      <div className="flex justify-end items-center mb-0.5 pb-0.5 border-b border-gray-6">
        <Button
          mode="pill"
          onClick={() => setIsMarkdownView(true)}
          className={`bg-gray-2 border border-gray-6 text-gray-12 size-3`}
        >
          <PlayIcon className="icon" />
        </Button>
      </div>
      <LexicalComposer
        initialConfig={{
          ...viewerConfig,
          editorState: (editor: LexicalEditor) => {
            editor.update(() => {
              if (!content) return
              $convertFromMarkdownString(
                content,
                [HR, IMAGE, CHECK_LIST, ...TRANSFORMERS],
                undefined,
                true
              )
            })
          },
        }}
      >
        <RichTextPlugin
          contentEditable={
            <ScrollArea className="w-full rounded-sm" style={{ height: height || '400px' }}>
              <div className="px-1">
                <ContentEditable className="outline-none text-gray-12 cursor-default" />
              </div>
              <ScrollBar orientation="horizontal" />
            </ScrollArea>
          }
          placeholder={
            <div className="text-gray-11 absolute top-1 left-1 pointer-events-none select-none">
              No content available
            </div>
          }
          ErrorBoundary={LexicalErrorBoundary}
        />
        <ListPlugin />
        <ClickableLinkPlugin />
      </LexicalComposer>
    </div>
  )
}
